local CX, CZ = 800, 310 -- titik tengah peta SVG

local function ke3D(x, y, h)
	return Vector3.new((x - CX) * SKALA, h, (y - CZ) * SKALA)
end

-- segitiga dari 2 WedgePart
local function segitiga(a, b, c, warna, induk)
	local ab, ac, bc = b - a, c - a, c - b
	if ac:Cross(ab).Magnitude < 0.01 then return 0 end
	local abd, acd, bcd = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
	if abd > acd and abd > bcd then
		c, a = a, c
	elseif acd > bcd and acd > abd then
		a, b = b, a
	end
	ab, ac, bc = b - a, c - a, c - b
	local right = ac:Cross(ab).Unit
	local up = bc:Cross(right).Unit
	local back = bc.Unit
	local height = math.abs(ab:Dot(up))
	local function wedge(size, cf)
		local w = Instance.new("WedgePart")
		w.Anchored = true
		w.CanCollide = true
		w.CastShadow = false
		w.Material = Enum.Material.SmoothPlastic
		w.Color = warna
		w.Size = size
		w.CFrame = cf
		w.Parent = induk
	end
	wedge(Vector3.new(TEBAL, height, math.abs(ab:Dot(back))), CFrame.fromMatrix((a + b) / 2, right, up, back))
	wedge(Vector3.new(TEBAL, height, math.abs(ac:Dot(back))), CFrame.fromMatrix((a + c) / 2, -right, up, -back))
	return 2
end

-- ear clipping: pecah poligon jadi segitiga
local function cross(ax, ay, bx, by, cx, cy)
	return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
end

local function triangulasi(P)
	local n = #P
	local idx = {}
	local luas = 0
	for i = 1, n do
		local j = i % n + 1
		luas = luas + P[i][1] * P[j][2] - P[j][1] * P[i][2]
	end
	if luas > 0 then
		for i = 1, n do idx[i] = i end
	else
		for i = 1, n do idx[i] = n - i + 1 end
	end
	local hasil = {}
	local i, gagal = 1, 0
	while #idx > 3 do
		local m = #idx
		local ia, ib, ic = idx[(i - 2) % m + 1], idx[i], idx[i % m + 1]
		local a, b, c = P[ia], P[ib], P[ic]
		local cembung = cross(a[1], a[2], b[1], b[2], c[1], c[2]) > 0
		local telinga = cembung
		if telinga then
			for k = 1, m do
				local id = idx[k]
				if id ~= ia and id ~= ib and id ~= ic then
					local p = P[id]
					if cross(a[1], a[2], b[1], b[2], p[1], p[2]) >= 0
						and cross(b[1], b[2], c[1], c[2], p[1], p[2]) >= 0
						and cross(c[1], c[2], a[1], a[2], p[1], p[2]) >= 0 then
						telinga = false
						break
					end
				end
			end
		end
		if telinga or gagal >= m then
			if telinga or cembung then table.insert(hasil, {ia, ib, ic}) end
			table.remove(idx, i)
			gagal = 0
			if i > #idx then i = 1 end
		else
			gagal = gagal + 1
			i = i % m + 1
		end
	end
	if #idx == 3 then table.insert(hasil, {idx[1], idx[2], idx[3]}) end
	return hasil
end

local function parseRing(s)
	local angka = {}
	for v in string.gmatch(s, "[^,]+") do angka[#angka + 1] = tonumber(v) end
	local P = {}
	for i = 1, #angka, 2 do P[#P + 1] = {angka[i], angka[i + 1]} end
	return P
end

-- bersihkan peta lama
local lama = workspace:FindFirstChild("PetaIndonesia")
if lama then lama:Destroy() end

local peta = Instance.new("Model")
peta.Name = "PetaIndonesia"

-- laut
local laut = Instance.new("Part")
laut.Name = "Laut"
laut.Anchored = true
laut.Size = Vector3.new(1700 * SKALA, 1, 700 * SKALA)
laut.Position = Vector3.new(0, -TEBAL / 2 - 0.5, 0)
laut.Color = WARNA_LAUT
laut.Material = Enum.Material.SmoothPlastic
laut.Parent = peta
peta.Parent = workspace

local jumlah = 0
for _, prov in ipairs(DATA) do
	local model = Instance.new("Model")
	model.Name = prov.n
	local warna = Color3.fromRGB(prov.c[1], prov.c[2], prov.c[3])
	local batas = Instance.new("Folder")
	batas.Name = "Batas"
	batas.Parent = model

	for _, ring in ipairs(prov.r) do
		local P = parseRing(ring.p)
		local air = ring.l % 2 == 1
		local tinggi = ring.l * 0.2
		local wr = air and WARNA_DANAU or warna
		local V = {}
		for k, p in ipairs(P) do V[k] = ke3D(p[1], p[2], tinggi) end
		for _, t in ipairs(triangulasi(P)) do
			jumlah = jumlah + segitiga(V[t[1]], V[t[2]], V[t[3]], wr, model)
		end
		-- garis batas
		for k = 1, #V do
			local a, b = V[k], V[k % #V + 1]
			local d = (b - a).Magnitude
			if d > 0.05 then
				local g = Instance.new("Part")
				g.Anchored = true
				g.CanCollide = false
				g.CastShadow = false
				g.Material = Enum.Material.SmoothPlastic
				g.Color = WARNA_BATAS
				g.Size = Vector3.new(LEBAR_BATAS, TEBAL, d + LEBAR_BATAS * 0.5)
				g.CFrame = CFrame.lookAt((a + b) / 2 + Vector3.new(0, 0.1 + tinggi, 0), b + Vector3.new(0, 0.1 + tinggi, 0))
				g.Parent = batas
			end
		end
		if jumlah % 200 < 6 then task.wait() end
	end

	-- label nama provinsi
	local jangkar = Instance.new("Part")
	jangkar.Name = "Label"
	jangkar.Anchored = true
	jangkar.CanCollide = false
	jangkar.Transparency = 1
	jangkar.Size = Vector3.new(1, 1, 1)
	jangkar.Position = ke3D(prov.x, prov.y, 4)
	jangkar.Parent = model
	local bb = Instance.new("BillboardGui")
	bb.Size = UDim2.fromOffset(150, 26)
	bb.AlwaysOnTop = true
	bb.MaxDistance = 1500
	bb.Parent = jangkar
	local tl = Instance.new("TextLabel")
	tl.Size = UDim2.fromScale(1, 1)
	tl.BackgroundTransparency = 1
	tl.Text = prov.n
	tl.TextScaled = true
	tl.Font = Enum.Font.GothamBold
	tl.TextColor3 = Color3.new(1, 1, 1)
	tl.TextStrokeTransparency = 0.3
	tl.Parent = bb

	model:SetAttribute("Provinsi", prov.n)
	model.Parent = peta
	task.wait()
end

-- titik spawn di Jawa Tengah
for _, prov in ipairs(DATA) do
	if prov.n == "Jawa Tengah" then
		local sp = Instance.new("SpawnLocation")
		sp.Anchored = true
		sp.Transparency = 1
		sp.Size = Vector3.new(8, 1, 8)
		sp.Position = ke3D(prov.x, prov.y, 3)
		sp.Parent = peta
	end
end

print("Peta Indonesia selesai: " .. jumlah .. " segitiga-wedge")
